                DataTable dt = ds.Tables[0];
                name = dt.AsEnumerable().Where(s=>CastAide.AsString(s["exchangeId"]) == currencyId).Select(s=> CastAide.AsString(s["currency"])).FirstOrDefault();

            }
            catch (Exception ex)
