        public bool SendPrivateMsgToUsers(DataTable dtMsg, string matchId, Message pmsg)
        {
            bool result = false;
            try
            {
                #region send private message to users
                if (dtMsg != null && dtMsg.Rows.Count > 0)
                {
                    if (dtMsg.Rows.Count > 0)
                    {
                        Hashtable list = new Hashtable();

                        for (int i = 0; i < dtMsg.Rows.Count; i++)
                        {

                            string[] ArrColumnsNameDownLineID = { "custid", "recommend", "mrecommend", "srecommend" };
                            string[] ArrColumnsNameDownLineUserName = { "CustUserName", "AgUserName", "MagUserName", "SagUserName" };

                            for (int j = 0; j < ArrColumnsNameDownLineID.Length; j++)
                            {
                                string cnameID = ArrColumnsNameDownLineID[j];
                                string cnameUser = ArrColumnsNameDownLineUserName[j];

                                string custid = dtMsg.Rows[i][cnameID].ToString();
                                string uname = dtMsg.Rows[i][cnameUser].ToString();

                                string key = custid + "^" + uname;
                                string ticknum = dtMsg.Rows[i]["transid"].ToString();

                                if (list[key] != null)
                                {
                                    if (list[key].ToString().IndexOf(ticknum) == -1)
                                    {
                                        string _tmp = list[key].ToString();
                                        list.Remove(key);
                                        list.Add(key, _tmp + "," + ticknum);
                                    }
                                }
                                else
                                    list.Add(key, ticknum);
                            }
                        }

                        DataTable dtDeletedBet = new DataTable();
                        dtDeletedBet.Columns.Add("custid", typeof(int));
                        dtDeletedBet.Columns.Add("username", typeof(string));
                        dtDeletedBet.Columns.Add("transids", typeof(string));
                        dtDeletedBet.Columns.Add("betcount", typeof(int));

                        foreach (DictionaryEntry Key in list)
                        {
                            int custid = CastAide.AsInt32(Key.Key.ToString().Split('^')[0]); // This is a CustID of ticket that is deleted [TargetID Field]
                            string uname = Key.Key.ToString().Split('^')[1];//This is a UserName of ticket that is deleted [TargetName Field]

                            DataRow dr = dtDeletedBet.NewRow();
                            dr["custid"] = custid;
                            dr["username"] = uname;
                            string[] ArrTransids = Key.Value.ToString().Split(',');
                            Array.Sort(ArrTransids);
                            string strTransIDs = "";
                            for (int i = 0; i < ArrTransids.Length; i++)
                            {
                                strTransIDs += ArrTransids[i] + ", ";
                            }
                            strTransIDs = strTransIDs.Substring(0, strTransIDs.Length - 2);
                            dr["transids"] = strTransIDs;
                            dr["betcount"] = Key.Value.ToString().Split(',').Length;
                            dtDeletedBet.Rows.Add(dr);
                        }
                        DataView dv = dtDeletedBet.DefaultView;
                        dv.Sort = "betcount asc, transids asc";
                        DataTable dtBets = dv.ToTable();

                        string strTransID_Current = "";
                        if (dtBets.Rows.Count > 0)
                            strTransID_Current = CastAide.AsString(dtBets.Rows[0]["transids"]);
                        int CountBetsBelong1Member = CastAide.AsInt32(dtBets.Compute("count(transids)", "transids='" + strTransID_Current + "'"));

                        // send private message to users for cancel their transactions                                                                                                                
                        int MessageId = 0;
                        foreach (DataRow dr in dtBets.Rows)
                        {
                            int[] custid = { CastAide.AsInt32(dr["custid"]) }; // This is a CustID of ticket that is deleted [TargetID Field]
                            string[] uname = { CastAide.AsString(dr["username"]) };//This is a UserName of ticket that is deleted [TargetName Field]

                            if (CastAide.AsInt32(dr["custid"]) < 100) continue;//SRecommend < 100 and roleid=3 
                            string[] bettransid = { CastAide.AsString(dr["transids"]) };

                            if (MessageId == 0)
                                MessageId = _IMessageService.SetMessage(pmsg, custid, uname, CastAide.AsInt32(matchId), bettransid);
                            else
                                _IMessageService.AddTargt2Message(MessageId, custid, uname, bettransid);
                        }
                    }
                }
                #endregion

                result = true;
            }
            catch (Exception ex)
            {
                result = false;
                LogExtensions.ExceptionHandler(ex);
            }

            return result;
        }

        public string UppercaseFirst(string s)
        {
            // Check for empty string.
            if (string.IsNullOrEmpty(s))
            {
                return string.Empty;
            }
            // Return char and concat substring.
            return s.ToLower();
        }

        public List<BettypeModel> SelBettype(Product.ProductType productType)
        {
            List<BettypeModel> list = new List<BettypeModel>();
            try
            {
                var ds = _baseDataAccess.SelBettype(productType);
                if (ds != null && ds.Tables.Count > 0)
                {
                    DataTable dt = ds.Tables[0];

                    bool [] liveindicators = {false, true };
                    foreach (bool liveindicator in liveindicators)
                    {
                        var rows = dt.AsEnumerable().Where(s => CastAide.AsBoolean(s["liveindicator"]) == liveindicator).ToList();
                        
                        BettypeModel bettypes = new BettypeModel();
                        bettypes.IsLive = liveindicator;
                        list.Add(bettypes);

                        foreach (DataRow row in rows)
                        {
                            int id = CastAide.AsInt32(row["typeId"]);
                            bettypes.Bettypes.Add(new Bettype() {
                                Id = id,
                                Name = CastAide.AsString(row["bettypeName"]) + (id == 90 ? (liveindicator ? " (Live Game)" : " (Pre Game)") : string.Empty),
                            });
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return list; 
        }

        /// <summary>
        /// SelNegativeBalanceCustomer
        /// </summary>
        /// <param name="transids"></param>
        /// <param name="actionType"></param>
        /// <param name="excludeRunning">excludeRunning = true when deleting bets of LCS </param>
        /// <returns></returns>
        public List<NegativeBalance> SelNegativeBalanceCustomer(string transids, Function.ActionType actionType, bool excludeRunning)
        {
            List<NegativeBalance> list = new List<NegativeBalance>();
            try
            {
                DataSet ds = _baseDataAccess.SelNegativebalance(transids, actionType, excludeRunning);

                if (ds == null || ds.Tables.Count == 0)
                    return list;

                DataTable dt = ds.Tables[0];
                var rows = dt.AsEnumerable().Where(s => CastAide.AsBoolean(s["IsNegative"]) == true);
                foreach (DataRow row in rows)
                {
                    list.Add(new NegativeBalance()
                    {
                        CustId = CastAide.AsInt32(row["custid"]),
                        UserName = CastAide.AsString(row["username"]),
                        IsNegative = CastAide.AsBoolean(row["IsNegative"])
                    });
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return list;
        }

        public string ConvertBeteamOfNumberGame(int bettype, string betteam)
        {
            betteam = betteam.ToLower();
            string rs = betteam;
            switch (bettype)
            {
                case 81:
                case 82:
                case 85:
                    rs = betteam == "h" ? "Over" : "Under";
                    break;
                case 83:
                case 84:
                case 86:
                    rs = betteam == "h" ? "Odd" : "Even";
                    break;
                case 87:
                    rs = betteam == "h" ? "Hight" : "Low";
                    break;
                case 88:
                    rs = betteam == "h" ? "2nd ball to win" : "3rd ball to win";
                    break;
                case 89:
                    switch (betteam)
                    {
                        case "1:1":
                            rs = "Over/Odd ";
                            break;
                        case "1:2":
                            rs = "Over/Even ";
                            break;
                        case "2:1":
                            rs = "Under/Odd ";
                            break;
                        case "2:2":
                            rs = "Under/Even ";
                            break;
                        default:
                            rs = "Over/Odd ";
                            break;
                    }
                    break;

            }
            return rs; 
        }

        public bool isValidInt64(string num, bool isAllowNullOrEmpty)
        {
            if (string.IsNullOrEmpty(num) && isAllowNullOrEmpty)
                return true;

            try
            {

                if (Int64.Parse(num) > Int64.MaxValue || Int64.Parse(num) < Int64.MinValue)
                    return false;
            }

            catch (Exception)
            {
                return false;
            }
            return true;
        }

        public bool isValidInt64(string nums, bool isAllowNullOrEmpty, string separator, ref string numInvalid)
        {
            var arr_Nums = nums.Split(separator.ToCharArray());
            foreach (string num in arr_Nums)
            {
                if (!isValidInt64(num, isAllowNullOrEmpty))
                {
                    numInvalid = num;
                    return false;
                }
            }
            return true;
        }

        public bool CheckMaxLengthTransId(ResultModel result, string transids_n,
           string transids_d,
           string transids_bd,
           string transids_12eu,
           string transids_mhc)
        {
            bool isSuccess = true;
            try
            {
                int maxlength = Fanex.Tarus.SpecialDelete.SendEmail.Core.Helper.MaxLengthInputParam;

                Dictionary<string, string> group = new Dictionary<string, string>();
                group.Add("Normal", transids_n);
                group.Add("Deposit", transids_d);
                group.Add("BetDaq", transids_bd);
                group.Add("12EU", transids_12eu);
                group.Add("MHC", transids_mhc);

                List<string> groupName = new List<string>();
                foreach (var g in group)
                {
                    if (g.Value.Length > maxlength)
                    {
                        groupName.Add(g.Key);
                    }
                }

                if (groupName.Count > 0)
                {
                    result.IsSuccess = false;
                    result.ErrorHandler.Add(new Result() { 
                        Key = "150",
                        Value = "You are not allowed to delete too many tickets of "+ string.Join(", ", groupName) +" at the same time.<br/>Please separate your list into smaller one!"
                    });
                    isSuccess = false;
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
                result.ErrorHandler.Add(new Result()
                {
                    Key = "150",
                    Value = ex.Message
                });
                isSuccess = false;
            }
            return isSuccess;
        }


